import React, { useEffect, useState } from 'react';
const thStyle = { textAlign: 'left', padding: '8px 12px', borderBottom: '1px solid #eee' };
const tdStyle = { padding: '8px 12px', borderBottom: '1px solid #f6f6f6' };
const rowEven = { background: '#fafafa' };
const btnPrimary = { marginRight: 8, padding: '6px 10px', cursor: 'pointer' };
const btnDanger = { padding: '6px 10px', cursor: 'pointer', background: 'transparent', border: '1px solid #e74c3c', color: '#e74c3c' };


function EditForm({ user, onCancel, onSave }) {
const [form, setForm] = useState({ ...user });
const [saving, setSaving] = useState(false);


useEffect(() => {
setForm({ ...user });
}, [user]);


function onChange(e) {
const { name, value } = e.target;
setForm(prev => ({ ...prev, [name]: value }));
}


async function submit(e) {
e.preventDefault();
setSaving(true);
const ok = await onSave(form);
setSaving(false);
if (!ok) {
// stay in edit mode so user can try again
}
}


return (
<form onSubmit={submit} style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
<div style={{ gridColumn: '1 / span 1' }}>
<label style={{ display: 'block', fontSize: 12 }}>Tên</label>
<input name="name" value={form.name ?? ''} onChange={onChange} style={inputStyle} />
</div>


<div style={{ gridColumn: '1 / span 1' }}>
<label style={{ display: 'block', fontSize: 12 }}>Email</label>
<input name="email" value={form.email ?? ''} onChange={onChange} style={inputStyle} />
</div>


<div>
<label style={{ display: 'block', fontSize: 12 }}>Số điện thoại</label>
<input name="phone" value={form.phone ?? ''} onChange={onChange} style={inputStyle} />
</div>


<div>
<label style={{ display: 'block', fontSize: 12 }}>Địa chỉ</label>
<input name="address" value={form.address ?? ''} onChange={onChange} style={inputStyle} />
</div>


<div style={{ gridColumn: '1 / span 2', marginTop: 8 }}>
<button type="submit" disabled={saving} style={{ padding: '8px 12px', marginRight: 8 }}>
{saving ? 'Đang lưu...' : 'Lưu'}
</button>
<button type="button" onClick={onCancel} style={{ padding: '8px 12px' }}>Hủy</button>
</div>
</form>
);
}


const inputStyle = {
width: '100%',
padding: '8px',
boxSizing: 'border-box',
border: '1px solid #ddd',
borderRadius: 4
};
